import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Mini-Programs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/miniapps.md","filePath":"guide/miniapps.md","lastUpdated":1791309864000}'),i={name:"guide/miniapps.md"};function n(d,e,s,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="mini-programs" tabindex="-1">Mini-Programs <a class="header-anchor" href="#mini-programs" aria-label="Permalink to &quot;Mini-Programs&quot;">​</a></h1><p>nPlyr can run <strong>hikerView-compatible mini-programs</strong> — the same community rules that power the Android app. This page explains what they are and how nPlyr executes them. For the compatibility boundary (especially the Java/Rhino parts), read the <a href="/guide/miniapp-compatibility.html">Compatibility</a> page.</p><h2 id="what-is-a-mini-program" tabindex="-1">What is a mini-program? <a class="header-anchor" href="#what-is-a-mini-program" aria-label="Permalink to &quot;What is a mini-program?&quot;">​</a></h2><p>A mini-program in this ecosystem is a <strong>rule package</strong> (HTML + JavaScript) that tells the app how to:</p><ul><li>render a <strong>home page</strong> of categories / channels,</li><li>run a <strong>search</strong>,</li><li>parse a <strong>list</strong> and a <strong>detail</strong> page, and</li><li>extract <strong>playable links</strong> and hand them to the player.</li></ul><p>The rule logic runs in a JavaScript engine and talks to the host app through a bridge object called <strong><code>fy_bridge_app</code></strong> (short: <strong><code>fba</code></strong>).</p><h2 id="the-contract-nplyr-reimplements" tabindex="-1">The contract nPlyr reimplements <a class="header-anchor" href="#the-contract-nplyr-reimplements" aria-label="Permalink to &quot;The contract nPlyr reimplements&quot;">​</a></h2><p>nPlyr does <strong>not</strong> port hikerView&#39;s Android/Java UI. Instead it reuses the layer that actually carries the value — the <strong>rule engine, the parse DSL and the mini-program bridge contract</strong> — and rewrites the UI, WebView and network layers natively for Apple platforms.</p><p>Concretely, nPlyr provides a native implementation of:</p><ul><li>the <strong>rule DSL</strong>: <code>pdfh</code> / <code>pdfa</code> / <code>pd</code> selectors, <code>parseDom</code>, <code>setHomeResult</code>, <code>setSearchResult</code>, <code>setResult</code>;</li><li>the <strong><code>$</code> selector compatibility layer</strong> so <code>$(url).lazyRule(fn)</code> and <code>$(url, ordinary).lazyRule</code> behave as expected;</li><li>the <strong><code>fy_bridge_app</code> / <code>fba</code> bridge</strong> so rules can call host features: play, fetch, post, parse, store variables;</li><li>the <strong><code>hiker://</code> pseudo-protocol</strong> routing (including <code>hiker://empty##…</code> as a lightweight parameter carrier and <code>hiker://search?s=</code> for aggregated search);</li><li>the <strong><code>lazyRule</code> / <code>.rule(fn)</code></strong> execution model, page navigation (<code>beginResultNavigation</code> / <code>finalizeResultPage</code>) and the result-stack lifecycle (<code>onClose</code> ownership, <code>MY_PAGE</code> attribution).</li></ul><h2 id="rule-dsl-essentials" tabindex="-1">Rule DSL essentials <a class="header-anchor" href="#rule-dsl-essentials" aria-label="Permalink to &quot;Rule DSL essentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>Purpose</th></tr></thead><tbody><tr><td><code>setHomeResult([…])</code></td><td>Emit the home grid (categories / channels).</td></tr><tr><td><code>setSearchResult([…])</code></td><td>Emit search results.</td></tr><tr><td><code>lazyRule</code> / <code>.rule(fn)</code></td><td>Run a sub-rule to parse a list/detail page.</td></tr><tr><td><code>fetch</code> / <code>post</code></td><td>HTTP with headers; <code>withHeaders</code> / <code>onlyHeaders</code> / <code>withStatusCode</code> return a JSON envelope.</td></tr><tr><td><code>putVar</code> / <code>getVar</code> / <code>putMyVar</code> / <code>getMyVar</code></td><td>In-memory variables; <code>setItem</code> / <code>getItem</code> / <code>clearItem</code> persist to local storage.</td></tr><tr><td><code>MY_URL</code> / <code>MY_RULE</code></td><td>The current rule&#39;s URL and rule body.</td></tr><tr><td><code>AES</code> / <code>RSA</code> / <code>CryptoJS</code></td><td>Crypto helpers available to rules.</td></tr></tbody></table><p>Each list item carries a <code>col_type</code> that nPlyr maps to a SwiftUI layout — there are <strong>38 <code>col_type</code> layouts</strong> (e.g. <code>text_1</code>, <code>pic_19</code>) aligned with hikerView&#39;s own item templates, so existing rules render the way their authors intended.</p><h2 id="managing-mini-programs" tabindex="-1">Managing mini-programs <a class="header-anchor" href="#managing-mini-programs" aria-label="Permalink to &quot;Managing mini-programs&quot;">​</a></h2><p>Open <strong>Mini-Programs</strong> (the manager window on macOS; a tab/page on iOS) to:</p><ul><li><strong>import</strong> a program from a share text or JSON,</li><li><strong>add / edit</strong> a rule (a full rule editor on macOS; a push page on iOS),</li><li><strong>reorder</strong> programs (drag) — the home top row follows the order,</li><li><strong>delete</strong> a program,</li><li><strong>share / cloud-share</strong> a program (cloud backends: TextDB, <code>cmd.im</code> 302 redirect, and <code>pasteme</code>).</li></ul><p>A <strong>free tier</strong> caps the number of imported mini-programs; a one-time unlock removes the cap.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>The independent search window is built from the rules you have installed that declare a <code>search_url</code>. You can search one engine or aggregate across all of them.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/guide/miniapp-compatibility.html">Compatibility</a> — exactly which Java/Rhino behaviors are and are not supported.</li><li><a href="/guide/downloads.html">Downloads &amp; Library</a> — where parsed links go.</li><li><a href="/guide/browser.html">Browser &amp; Sniffer</a> — the alternative path for capturing links.</li></ul><h2 id="official-hikerview-documentation" tabindex="-1">Official hikerView documentation <a class="header-anchor" href="#official-hikerview-documentation" aria-label="Permalink to &quot;Official hikerView documentation&quot;">​</a></h2><p>nPlyr is built to be compatible with the hikerView rule ecosystem. For the complete rule and mini-program reference — the DSL, selectors, bridge contract and authoring guides — see the official hikerView documentation:</p><ul><li><strong>hikerView Docs:</strong> <a href="https://github.com/ReflectionLab/Documents" target="_blank" rel="noreferrer">https://github.com/ReflectionLab/Documents</a></li></ul><p>If you already write rules for hikerView, the same share texts and JSON import and run unchanged in nPlyr (subject to the compatibility boundary above).</p>',25)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
